DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PayLab Live</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;font:14px/1.5 Inter,system-ui,sans-serif;background:#08101f;color:#eaf1ff}main{max-width:1180px;margin:auto;padding:32px 20px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}h1{font-size:34px;margin:0}.muted{color:#8ea0c4}.status{padding:7px 11px;border:1px solid #304160;border-radius:999px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:24px 0}.card{background:#111b30;border:1px solid #263753;border-radius:16px;padding:18px}.metric{font-size:30px;font-weight:800;margin-top:4px}.events{display:grid;gap:10px}.event{display:grid;grid-template-columns:170px 1fr 130px;gap:12px;align-items:center;background:#0d172a;border:1px solid #223451;border-radius:12px;padding:13px}.badge{display:inline-block;padding:3px 8px;border-radius:999px;background:#1c2a45}.ok{color:#70e3a2}.bad{color:#ff8e8e}@media(max-width:760px){.grid{grid-template-columns:1fr}.event{grid-template-columns:1fr}}</style></head>
<body><main><div class="top"><div><div class="muted">PAYMENT RELIABILITY CONSOLE</div><h1>PayLab Live</h1></div><div id="socketStatus" class="status">Connecting…</div></div><div class="grid"><div class="card"><div class="muted">Recent events</div><div id="eventCount" class="metric">0</div></div><div class="card"><div class="muted">Acknowledged deliveries</div><div id="successRate" class="metric">—</div></div><div class="card"><div class="muted">Providers active</div><div id="providerCount" class="metric">0</div></div></div><div class="card"><div class="top"><div><div class="muted">LIVE FEED</div><h2>Webhook activity</h2></div><button id="refresh">Refresh</button></div><div id="events" class="events"></div></div></main>
<script>const state={events:[]};function acknowledged(e){return e.deliveries.length>0&&e.deliveries.every(d=>d.status_code!==null&&d.status_code>=200&&d.status_code<300)}function render(){const root=document.getElementById('events');root.textContent='';const providers=new Set();let successful=0,total=0;state.events.forEach(e=>{providers.add(e.provider);e.deliveries.forEach(d=>{total++;if(d.status_code!==null&&d.status_code>=200&&d.status_code<300)successful++});const row=document.createElement('div');row.className='event';const time=document.createElement('div');time.className='muted';time.textContent=e.created_at?new Date(e.created_at).toLocaleString():'Live';const main=document.createElement('div');const title=document.createElement('strong');title.textContent=e.provider+' / '+e.event;const id=document.createElement('div');id.className='muted';id.textContent=e.event_id;main.append(title,id);const result=document.createElement('div');result.className='badge '+(acknowledged(e)?'ok':'bad');result.textContent=acknowledged(e)?'ACK':'CHECK';row.append(time,main,result);root.append(row)});document.getElementById('eventCount').textContent=state.events.length;document.getElementById('providerCount').textContent=providers.size;document.getElementById('successRate').textContent=total?Math.round(successful/total*100)+'%':'—'}async function load(){const res=await fetch('/v1/history/events?limit=50');state.events=await res.json();render()}function connect(){const scheme=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(scheme+'://'+location.host+'/v1/stream');const label=document.getElementById('socketStatus');ws.onopen=()=>{label.textContent='Live';label.className='status ok'};ws.onclose=()=>{label.textContent='Reconnecting…';label.className='status';setTimeout(connect,1500)};ws.onmessage=m=>{const p=JSON.parse(m.data);if(p.type==='delivery.completed'){state.events.unshift({...p.event,created_at:new Date().toISOString()});state.events=state.events.slice(0,50);render()}}}document.getElementById('refresh').addEventListener('click',load);load();connect();</script></body></html>"""
